# ── blok 67:21-30 (2026-10-25) ──
MEAL3 = {
 21: "Yoksa O rızkını keserse, sizi rızıklandıracak olan bu kim? Hayır, onlar azgınlık ve kaçışta direnip duruyorlar.",
 22: "Yüzüstü kapanarak yürüyen mi daha doğru yoldadır, yoksa dosdoğru bir yol üzerinde dimdik yürüyen mi?",
 23: "De ki: 'Sizi var eden ve size işitme, görme ve gönüller veren O'dur. Ne az şükrediyorsunuz!'",
 24: "De ki: 'Sizi yeryüzünde yaratıp yayan O'dur ve O'nun huzurunda toplanacaksınız.'",
 25: "Ve diyorlar ki: 'Doğru söylüyorsanız bu tehdit ne zaman?'",
 26: "De ki: 'Bilgi ancak Allah katındadır; ben ancak apaçık bir uyarıcıyım.'",
 27: "Onu yakından gördüklerinde inkâr edenlerin yüzleri kararır ve denir ki: 'İşte çağırıp durduğunuz bu.'",
 28: "De ki: 'Söyleyin bakalım: Allah beni ve benimle birlikte olanları helâk etse ya da bize merhamet etse, inkâr edenleri acı bir azaptan kim koruyacak?'",
 29: "De ki: 'O Rahmân'dır; O'na inandık ve O'na dayandık. Kimin apaçık bir sapıklık içinde olduğunu yakında bileceksiniz.'",
 30: "De ki: 'Söyleyin bakalım: Suyunuz çekilip yerin dibine gitse, size akan suyu kim getirecek?'",
}

M3 = {
 21: "◇ 'emmen hâzâ'llezî yerzuqukum in emseke rizqah' — nakarat3 eşi 67:20 'em-men + zâ + ellezî' (okumada görüldü; GEÇMEZ). رزق sûre içi 67:15 'rizqihî' / 67:21 'yerzuqukum', 'rizqahû' (رزق [2,3/3]). مسك sûre içi 67:19 'mâ yumsikuhunne' (kuşları havada tutma) / 67:21 'in emseke rizqah' (rızkı alıkoyma) (مسك [2/2]) — aynı fiil iki anlamda (okuma). 'bel leccû fî utuvvin ve nufûr' — lemma 'lecce' 2 ayet: 23:75 ('le-leccû fî tuğyânihim ya'mehûn') (okumada görüldü), 67:21; lemma 'utuvv' 2 ayet: 25:21 ('ve atev utuvven kebîrâ') (okumada görüldü), 67:21; lemma 'nufûr' 5 ayet: okunmuş 4, 67:21; lemma dizisi 'utuvv + nufûr' korpusta 1. İdrâb 'bel' (ölçüm biçim IDRAB). Muhatap 2MP → 'leccû' 3MP (okuma; ölçüm iltifât 0). Lafız ve Rab yok; esmâ yok. 12 kelime, yıldızsız. رزق [2,3/3], مسك [2/2], لجج [1/1], عتو [1/1], نفر [1/1]. Fâsıla ر. Karşıt çift (aday 1039, okuma): yok.\n◈K — —\n◈B — —\n◈D — D1 'em-men' (soru) + işaret + mevsûl + IMPF + şart 'in' + PERF IV. bab + meful izâfet; 'bel' + PERF + câr + atıf; D2 soru (INTG), şart (COND), DIKKAT, idrâb (IDRAB) — ölçüm; D3 رزق ×2 (ölçüm ikileme); D4 2MP → 3MS → 3MP, sahset ['2', '3'].\n◈A — A1 2MP muhatap, 3MS (rızık veren, adsız), 3MP (direnenler, adsız); A2 —; A3 —; A4 soru dizisi sürüyor ve idrâbla 3MP hükmüne geçiyor (okuma).",
 22: "◇ 'e-fe-men yemşî mukibben alâ vechihî ehdâ' — lemma 'mukibb' korpusta 1 token; lemma dizisi 'men + meşâ + mukibb' korpusta 1. 'em-men yemşî seviyyen alâ sırâtin mustaqîm' — lemma 'sevî' 5 ayet: 19:43 ('ehdike sırâtan seviyyâ') (okumada görüldü), okunmuş 3 ayet daha, 67:22 — 19:43'te 'sevî' yolun sıfatı, burada yürüyenin hâli (okuma); lemma dizisi 'sırât + mustaqîm' 31 ayet: 1:6 ('ihdina's-sırâta'l-mustaqîm') (okumada görüldü), okunmuş 17 ayet daha, 67:22, henüz okunmamış 12 — 1:6'da 'ihdinâ', burada 'ehdâ' (هدي) aynı ayette (okuma). مشي ikilemesi 'yemşî' ×2 (مشي [2,3/3]); sûre içi 67:15 'imşû' (emir, yerin sırtlarında) (okuma). Fâsıla 67:1-21 ر → 67:22 م (R → N sınıfı) — bilanço kafiye kırığı işaretlemedi (924, ARIZA). Mesel: iki yürüyüş, karşılaştırma sorusu (okuma). Lafız ve Rab yok; esmâ yok. 12 kelime, yıldızsız. مشي [2,3/3], كبب [1/1], وجه [1/2], هدي [1/1], سوي [1/1], صرط [1/1], قوم [1/1]. Fâsıla م. Karşıt çift (aday 1039, okuma): 'mukibben alâ vechihî' / 'seviyyen alâ sırâtin mustaqîm' (yüzüstü / dimdik).\n◈K — —\n◈B — —\n◈D — D1 soru hemzesi + 'fe' + 'men' + IMPF + hâl + câr izâfet + tafdîl 'ehdâ'; 'em' + 'men' + IMPF + hâl + câr + sıfat; D2 soru (INTG) — ölçüm; mesel / karşılaştırma (okuma; ölçüm biçim yok); D3 مشي ×2 (ölçüm ikileme), aynı fiil iki hâlle; D4 3MS tek, sahset ['3'].\n◈A — A1 iki yürüyen (adsız, 'men'); A2 yol ('sırât'); A3 —; A4 mesel soru dizisinin içinde (okuma).",
 23: "◇ 'qul huve'llezî enşe'ekum ve ce'ale lekumu's-sem'a ve'l-ebsâra ve'l-ef'ide qalîlen mâ teşkurûn' — esit2 (ölçüm) → 23:78 ('ve huve'llezî enşe'e lekumu's-sem'a ve'l-ebsâra ve'l-ef'ide qalîlen mâ teşkurûn') (okumada görüldü) BENZER 0,9263; xref (ölçüm) → 23:78, 32:9 ('ve ce'ale lekumu's-sem'a ve'l-ebsâra ve'l-ef'ide qalîlen mâ teşkurûn') (okumada görüldü). Lemma dizisi 'sem' + basar + fuâd' 6 ayet: 23:78, 32:9 (okumada görüldü), okunmuş 3 ayet daha, 67:23; lemma dizisi 'qalîl + mâ + şekera' 4 ayet: 23:78, 32:9, 67:23, henüz okunmamış 1. 23:78'de 'enşe'e lekum' + organlar, 32:9'da 've ce'ale lekum' + organlar, burada 'enşe'ekum ve ce'ale lekum' ikisi birlikte (okuma). Lemma 'enşe'e' 20 ayet: 23:78 (okumada görüldü), okunmuş 14 ayet daha, 67:23, henüz okunmamış 4. 'qul' (2MS emir) sûre içinde ilk kez 67:23'te; 67:23-30'da 'qul' altı ayeti açıyor: 67:23, 24, 26, 28, 29, 30 (morph LEM; okuma). سمع sûre içi 67:7, 67:10, 67:23 (سمع [3/3]); بصر 67:3, 67:4 ×2, 67:19, 67:23 'el-ebsâr' (بصر [5/5]) (okuma). Sayı işareti 'qalîl' — sayı değil (924). Fâsıla ن (N sınıfı). Muhatap 2MS (adsız, 1017) → 2MP. Lafız ve Rab yok; esmâ yok. 12 kelime, yıldızsız. قول [5/12], نشأ [1/1], جعل [3/3], سمع [3/3], بصر [5/5], فأد [1/1], قلل [1/1], شكر [1/1]. Fâsıla ن. Karşıt çift (aday 1039, okuma): yok.\n◈K — —\n◈B — B1 insan (2MP, 'enşe'ekum'); B2 oluşum 'enşe'ekum' (var etme), aşama yok; B3 organlar 'es-sem'' (işitme), 'el-ebsâr' (gözler), 'el-ef'ide' (gönüller) — verilmiş yetiler olarak, şükür beklentisiyle; B4 —.\n◈D — D1 IMPV 'qul' + zamir + mevsûl + PERF IV. bab + atıf PERF + câr + meful ×3; 'qalîlen' + 'mâ' + IMPF; D2 emir (IMPV) — ölçüm; şükürsüzlük tespiti (okuma); D3 —; D4 2MS ('qul') → 3MS → 2MP, sahset ['2', '3'].\n◈A — A1 2MS muhatap ('qul', adsız), 3MS (var eden), 2MP; A2 —; A3 2MS'ye söylenecek söz verilmiş (alıntı açılışı); A4 'qul' dizisi açılıyor (okuma).",
 24: "◇ 'qul huve'llezî zere'ekum fi'l-ard' — esit2 (ölçüm) → 23:79 ('ve huve'llezî zere'ekum fi'l-ardi ve ileyhi tuhşerûn') (okumada görüldü) BENZER 0,9492; lemma dizisi 'ellezî + zere'e + fî + ard' 2 ayet: 23:79, 67:24. 23:78-79 ↔ 67:23-24 aynı sırayla iki ayet eşleşiyor — ardışık sûre değil, okuma bağı (okuma). 've ileyhi tuhşerûn' — lemma dizisi 'ilâ + haşera' 7 ayet: 23:79 (okumada görüldü), okunmuş 1 ayet daha, 67:24, henüz okunmamış 4. nakarat3 'qul huve'llezî' eşi 67:23 (GEÇMEZ). أرض sûre içi 67:15 'zelûl', 67:16 'temûr', 67:24 'zere'ekum fi'l-ard' (أرض [3/3]); 67:15 'ileyhi'n-nuşûr' / 67:24 'ileyhi tuhşerûn' (okuma). Edilgen 'tuhşerûn' (ölçüm EDİLGEN 1/3, pas z=1,57; ★ pas, içerik iddiası değil). Lafız ve Rab yok; esmâ yok. 8 kelime. قول [6/12], ذرأ [1/1], أرض [3/3], حشر [1/1]. Fâsıla ن. Karşıt çift (aday 1039, okuma): 'zere'ekum fi'l-ard' / 'ileyhi tuhşerûn' (yeryüzüne yayma / O'na toplanma).\n◈K — K1 'el-ard'; K2 'tuhşerûn' ertelenmiş (gelecek, edilgen IMPF); K3 —; K4 'zere'ekum' (yaydı) — özne 3MS, nesne 2MP; toplanma edilgen, toplayan adlanmıyor (okuma).\n◈B — —\n◈D — D1 IMPV 'qul' + zamir + mevsûl + PERF + câr; 've' + câr + IMPF edilgen; D2 emir (IMPV), haber öne 'ileyhi' (okuma; ölçüm HASR yazmıyor); D3 67:23 açılış kalıbının tekrarı (nakarat3); D4 2MS → 3MS → 2MP, sahset ['2', '3'].\n◈A — A1 2MS muhatap, 3MS, 2MP; A2 yeryüzü / toplanma (ertelenmiş); A3 'qul' alıntısı sürüyor; A4 —.",
 25: "◇ 've yeqûlûne metâ hâze'l-va'du in kuntum sâdiqîn' — esit2 (ölçüm) YAKIN 0,9825 → 36:48 ('ve yeqûlûne metâ hâze'l-va'du in kuntum sâdiqîn') (okumada görüldü) ve okunmuş 4 ayet daha, BENZER okunmuş 1 ayet; lemma dizisi (2-7. kelime) 6 ayet: 36:48 (okumada görüldü), okunmuş 4 ayet daha, 67:25. İnkârcıların sorusu, adsız 3MP; 'kuntum' 2MP muhatap adsız (1017). 'qul' dizisinin arasında 'yeqûlûn' — iki konuşma sırası (okuma). Şart 'in' (ölçüm COND), soru 'metâ' (INTG). Lafız ve Rab yok; esmâ yok. 7 kelime, yıldızsız. قول [7/12], وعد [1/1], كون [4/5], صدق [1/1]. Fâsıla ن. Karşıt çift (aday 1039, okuma): yok.\n◈K — —\n◈B — —\n◈D — D1 've' + IMPF + soru 'metâ' + işaret + mubteda; şart 'in' + 'kâne' 2MP + haber; D2 soru (INTG), şart (COND), DIKKAT (ölçüm biçim); D3 —; D4 3MP → 2MP (alıntı içi), sahset ['2', '3'].\n◈A — A1 3MP konuşanlar (adsız), 2MP muhatap (adsız); A2 —; A3 karşı tarafın sorusu, cevap 67:26'da 'qul' ile (okuma); A4 —.",
 26: "◇ 'qul innema'l-ilmu inda'llâh' — lemma dizisi 'innemâ + ilm + ind + Allah' 4 ayet: 46:23 ('innema'l-ilmu inda'llâh') (okumada görüldü), okunmuş 1 ayet daha, 67:26, henüz okunmamış 1. 've innemâ ene nezîrun mubîn' — lemma dizisi 2 ayet: 29:50 ('qul innema'l-âyâtu inda'llâhi ve innemâ ene nezîrun mubîn') (okumada görüldü), 67:26; xref (ölçüm) → 29:50 ve okunmuş 1 ayet daha — 29:50'de 'el-âyât', burada 'el-ilm' Allah katında (okuma). Soru-cevap 67:25 'metâ' → 67:26 'innema'l-ilmu inda'llâh' (okuma). 'innemâ' ×2 hasrı ölçüm biçim alanında yok (okuma; ARIZA). نذر sûre içi dört geçiş, dördü okundu: 67:8, 67:9, 67:17, 67:26 (نذر [4/4]) — 67:26'da 1S 'ene nezîr' (okuma). Lafız sûre içi 67:9, 67:26 (أله [2/3]); 1S 'ene' konuşan 'qul' muhatabı (adsız; 1017). Esmâ 'mubîn' (9. kelime, son) — DEĞİL (karar; konuşan uyarıcının sıfatı); esma_kayit mühür EVET, karar sonrası geçersiz (bilanço; 1022). ★ allah z=1,69 (bilanço; içerik iddiası değil). 9 kelime. قول [8/12], علم [4/5], عند [1/1], أله [2/3], نذر [4/4], بين [1/2]. Fâsıla ن. Karşıt çift (aday 1039, okuma): 'el-ilmu inda'llâh' / 'ene nezîrun mubîn' (bilgi Allah katında / ben uyarıcıyım).\n◈K — —\n◈B — —\n◈D — D1 IMPV 'qul' + 'innemâ' + mubteda + zarf izâfet (lafız); 've innemâ' + zamir 1S + haber + sıfat; D2 hasr 'innemâ' ×2 (okuma; ölçüm HASR yazmıyor), emir (IMPV); D3 'innemâ' kalıbının tekrarı (okuma); D4 2MS → 1S, sahset ['1', '2'].\n◈A — A1 2MS ('qul') = 1S konuşan (adsız), Allah lafzı; A2 —; A3 67:25 sorusuna cevap; A4 —.",
 27: "◇ 'fe-lemmâ ra'evhu zulfeten sî'et vucûhu'llezîne keferû' — lemma 'zulfe' 2 ayet: okunmuş 1, 67:27; lemma dizisi 'sâ'e + vech' 2 ayet: 17:7 ('li-yesû'û vucûhekum') (okumada görüldü), 67:27. 'ra'evhu' 3MS zamiri 67:25 'el-va'd'a dönüyor (okuma). 've qîle hâzâ'llezî kuntum bihî teddeûn' — lemma dizisi korpusta 1; lemma 'iddeâ' 3 ayet: 36:57 ('ve lehum mâ yeddeûn') (okumada görüldü), okunmuş 1 ayet daha, 67:27 — 36:57'de cennettekilerin istedikleri, burada inkârcıların çağırıp durduğu (okuma; harekesiz kalıp 'teddeûn' / 'ted'ûn' gürültüsü, sayı lemmadan). Edilgen 'sî'et', 'qîle' (ölçüm EDİLGEN 2/6, pas z=1,57; ★ pas, içerik iddiası değil); 'qîle' konuşanı adlanmıyor (1017). Gelecek olay geçmiş zamanla (PERF 5) anlatılıyor (okuma). وجه sûre içi 67:22 'vechihî' / 67:27 'vucûh' (وجه [2/2]); كفر 67:6, 67:20, 67:27 (كفر [3/4]). Lafız ve Rab yok; esmâ yok. 13 kelime. رأي [4/6], زلف [1/1], سوأ [1/1], وجه [2/2], كفر [3/4], قول [9/12], كون [5/5], دعو [1/1]. Fâsıla ن. Karşıt çift (aday 1039, okuma): yok.\n◈K — —\n◈B — —\n◈D — D1 'fe-lemmâ' + PERF + meful zamir + hâl; cevap PERF edilgen + fail izâfet + mevsûl + PERF; atıf PERF edilgen + işaret + mevsûl + 'kâne' + câr + IMPF VIII. bab; D2 DIKKAT (ölçüm biçim), edilgen ×2; D3 —; D4 3MP → 2MP (alıntı içi), sahset ['2', '3'].\n◈A — A1 inkâr edenler (3MP, adsız), 'qîle' konuşanı adsız; A2 âhiret (yakına gelen tehdit); A3 67:25 sorusunun cevabı sahneyle (okuma); A4 sahne açılıp kapanıyor (okuma).",
 28: "◇ 'qul e-ra'eytum in ehlekeniye'llâhu ve men maiye ev rahimenâ' — lemma dizisi 'qâle + ra'â' 17 ayet: okunmuş 12, 67:28, sûre içi 67:30, henüz okunmamış 3; nakarat3 'qul e-ra'eytum in' eşi 67:30 (GEÇMEZ). 'fe-men yucîru'l-kâfirîne min azâbin elîm' — lemma dizisi korpusta 1; lemma 'ecâra' 5 ayet: okunmuş 3, 67:28, henüz okunmamış 1. Konuşan 1S 'ehlekenî', 'maiye' → 1P 'rahimenâ' (ölçüm 1S 2, 1P 1) — 'qul' muhatabı ve yanındakiler (adsız; 1017). Lafız sûre içi üçüncü ve son: 67:9, 67:26, 67:28 (أله [3/3]). رحم 67:28 'rahimenâ' (fiil, Allah için) — 67:3, 19, 20, 29 'er-rahmân' ile aynı kök (رحم [4/5]) (okuma). عذب sûre içi 67:5, 67:6, 67:28 (عذب [3/3]); كفر 67:6, 20, 27, 28 (كفر [4/4]). Lafız 15 kelimede 1 (bilanço lafız_token 2 blok içi). 15 kelime, yıldızsız. قول [10/12], رأي [5/6], هلك [1/1], أله [3/3], رحم [4/5], جور [1/1], كفر [4/4], عذب [3/3], ألم [1/1]. Fâsıla م. Karşıt çift (aday 1039, okuma): 'ehlekeniye'llâh' / 'rahimenâ' (helâk etme / merhamet etme).\n◈K — —\n◈B — —\n◈D — D1 IMPV 'qul' + soru hemzesi + PERF 'ra'eytum'; şart 'in' + PERF IV. bab + meful 1S + fail (lafız) + atıf 'men maiye' + 'ev' + PERF + meful 1P; 'fe-men' + IMPF IV. bab + meful + câr + sıfat; D2 soru ×2 (INTG), şart (COND), emir (IMPV) — ölçüm; şart sonucu soru (okuma); D3 —; D4 2MS → 2MP → 1S → 1P → 3MS → 3MP, sahset ['1', '2', '3'].\n◈A — A1 2MS ('qul') = 1S konuşan, yanındakiler (adsız), Allah lafzı, inkâr edenler (3MP); A2 —; A3 'qul' alıntısında 2MP'ye soru; A4 —.",
 29: "◇ 'qul huve'r-rahmânu âmennâ bihî ve aleyhi tevekkelnâ' — lemma dizisi (4-7. kelime) korpusta 1. 'fe-se-ta'lemûne men huve fî dalâlin mubîn' — lemma dizisi (8-13. kelime) korpusta 1; lemma dizisi 'fî + dalâl + mubîn' 18 ayet: okunmuş 14, 67:29, henüz okunmamış 3. 'fe-se-ta'lemûn' sûre içi 67:17, 67:29 (okuma); علم sûre içi beş geçiş, beşi okundu: 67:13, 14, 17, 26, 29 (علم [5/5]). ضلل 67:9 'dalâlin kebîr' / 67:29 'dalâlin mubîn' (ضلل [2/2]); بين 67:26 'nezîrun mubîn' (uyarıcı) / 67:29 'dalâlin mubîn' (sapıklık) (بين [2/2]) — aynı sıfat iki karşı gönderge için (okuma). رحم sûre içi beş geçiş, beşi okundu: 67:3, 19, 20, 28, 29 (رحم [5/5]). 1P 'âmennâ', 'tevekkelnâ' (ölçüm 1P 4) — 'qul' muhatabı ve yanındakiler (adsız). Esmâ 'rahmân' (3. kelime, orta) — İLÂHÎ; 'mubîn' (13. kelime, son) — DEĞİL (karar; sapıklığın sıfatı); bilanço geçerli mühür 67:29, oysa ayetin son esmâ tokeni 'DEĞİL' kararlı — mühür ölçütü karar sonrası konumla ayrışıyor (ARIZA; 1022). Lafız ve Rab yok. 13 kelime, yıldızsız. قول [11/12], رحم [5/5], أمن [3/3], وكل [1/1], علم [5/5], ضلل [2/2], بين [2/2]. Fâsıla ن. Karşıt çift (aday 1039, okuma): yok.\n◈K — —\n◈B — —\n◈D — D1 IMPV 'qul' + zamir + haber; PERF 1P + câr; 've' + câr + PERF V. bab 1P (haber öne); 'fe-se' + IMPF + 'men' + zamir + câr + sıfat; D2 emir (IMPV), gelecek (FUT) — ölçüm; câr öne 'aleyhi tevekkelnâ' (okuma; ölçüm HASR yazmıyor); D3 —; D4 2MS → 3MS → 1P → 2MP, sahset ['1', '2', '3'].\n◈A — A1 2MS ('qul'), 1P (konuşan ve yanındakiler, adsız), 'er-rahmân', 2MP muhatap; A2 —; A3 'qul' alıntısı; A4 sonuç ertelenmiş ('se-ta'lemûn') (okuma).",
 30: "◇ 'qul e-ra'eytum in asbaha mâ'ukum ğavran' — lemma dizisi 'asbaha + mâ' + ğavr' 2 ayet: 18:41 ('ev yusbiha mâ'uhâ ğavran fe-len testetî'a lehû talebâ') (okumada görüldü), 67:30; xref (ölçüm) → 18:41; lemma 'ğavr' 2 ayet: 18:41, 67:30 — 18:41'de bahçenin suyu ve 'len testetî'a' (yapamazsın) açık yeti sınırı, burada 'fe-men ye'tîkum' sorusu (okuma). 'fe-men ye'tîkum bi-mâ'in ma'în' — lemma dizisi korpusta 1; lemma 'ma'în' 4 ayet: 23:50 ('zâti qarârin ve ma'în') (okumada görüldü), okunmuş 2 ayet daha, 67:30. nakarat3 'qul e-ra'eytum in' eşi 67:28 (GEÇMEZ). 'mâ'' ×2 (موه [1,2/2]) — 'mâ'ukum' / 'bi-mâ'in'. Kök عين ◈B tetiği 'ma'în' (akan su) — organ anlamı değil, tetik kök düzeyinde (okuma). Sûre 'qul' ile açılan cevapsız soruyla kapanıyor (okuma). قول [12/12], رأي [6/6], أتي [2/2] — üçünün de sûre içi son geçişi (ölçüm). Fâsıla 67:23-30 ن (67:28 م). Lafız ve Rab yok; esmâ yok. 10 kelime, yıldızsız. قول [12/12], رأي [6/6], صبح [2/2], موه [1,2/2], غور [1/1], أتي [2/2], عين [1/1]. Fâsıla ن. Karşıt çift (aday 1039, okuma): 'ğavran' / 'ma'în' (çekilmiş su / akan su).\n◈K — K1 'mâ'' (su; ölçüm kökü موه) — 'ğavr' (yerin dibine çekilmiş) / 'ma'în' (akan); K2 'asbaha' (sabahlayıverme / oluverme; kök صبح gloss 'sabah; olmak'), birim yok, varsayımsal şart; K3 —; K4 hareket: suyun çekilmesi (özne su), getirme 'ye'tîkum' (özne 'men', cevapsız) (okuma).\n◈B — B1 —; B2 —; B3 kök عين 'ma'în' — pınar / akan su anlamında, organ değil (okuma); B4 —; su yaşam koşulu olarak anılmıyor, yalnız ihtiyaç soruda örtük (okuma; KAPATILAMAZ).\n◈D — D1 IMPV 'qul' + soru hemzesi + PERF 'ra'eytum'; şart 'in' + PERF 'asbaha' + ism izâfet + haber; 'fe-men' + IMPF + câr + sıfat; D2 soru ×2 (INTG), şart (COND), emir (IMPV) — ölçüm; 67:28 kalıbının tekrarı (nakarat3); D3 موه ×2 (ölçüm ikileme); D4 2MS → 2MP → 3MS, sahset ['2', '3'].\n◈A — A1 2MS ('qul'), 2MP muhatap, 'men' (adsız, cevapsız); A2 —; A3 'qul' alıntısı; A4 sûrenin kapanışı — cevapsız soru (okuma).",
}

